export type Topic = { title: string; category: string; status: string; they: string; record: string };

/** URL slug for a topic title — stable, ascii, unique across the archive. */
export function topicSlug(title: string): string {
  return title.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[ʻ''.]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

